using BenchmarkDotNet; using System; using System.Collections.Generic; using System.Linq; using System.Text; using System.Threading; using System.Threading.Tasks; using BenchmarkDotNet.Attributes; using BenchmarkDotNet.Jobs; using BenchmarkDotNet.Engines; using BenchmarkDotNet.Extensions; using BenchmarkDotNet.Math; using BenchmarkDotNet.Math.Statistics; using BenchmarkDotNet.Reports; using BenchmarkDotNet.Running; using BenchmarkDotNet.Statistics; using BenchmarkDotNet.Statistics.Median; using BenchmarkDotNet.Statistics.Variance; namespace AttributeAnalyzerBenchmarks { [MemoryDiagnoser] public class AttributeAnalyzerBenchmarks { [GlobalSetup] public void Setup() { } [Benchmark] public void Benchmark_AnalyzeAttribute() { var attributeAnalyzer = new AttributeAnalyzer(); var attributes = new List<Attribute>(); for (int i = 0; i < 100; i++) { attributes.Add(new Attribute { Name = "TestAttribute" + i, Description = "This is a test attribute" }); } attributeAnalyzer.Analyze(attributes); } [Benchmark] public void Benchmark_AnalyzeAttributes_MultipleTimes() { var attributeAnalyzer = new AttributeAnalyzer(); var attributes = new List<Attribute>(); for (int i = 0; i < 100; i++) { attributes.Add(new Attribute { Name = "TestAttribute" + i, Description = "This is a test attribute" }); } for (int i = 0; i < 10; i++) { attributeAnalyzer.Analyze(attributes); } } [Benchmark] public void Benchmark_AnalyzeAttribute_LargeData() { var attributeAnalyzer = new AttributeAnalyzer(); var attributes = new List<Attribute>(); for (int i = 0; i < 1000; i++) { attributes.Add(new Attribute { Name = "TestAttribute" + i, Description = "This is a test attribute" }); } attributeAnalyzer.Analyze(attributes); } } }